This function leaks the file handle on the early-return path. Add the missing close so the handle is always released, but otherwise leave the function exactly as it is.

```go
func readFirstLine(path string) (string, error) {
    f, err := os.Open(path)
    if err != nil {
        return "", err
    }
    sc := bufio.NewScanner(f)
    if !sc.Scan() {
        return "", sc.Err()
    }
    line := sc.Text()
    f.Close()
    return line, nil
}
